import {destinations} from './destinations.js';
const shortcuts=document.createElement('nav');shortcuts.className='portfolio-shortcuts';shortcuts.setAttribute('aria-label','Choose your experience');shortcuts.innerHTML='<a href="#expedition">Watch the story</a><a href="#journey">View portfolio</a><a href="#atlas">Explore destinations</a><a href="#contact">Contact</a>';document.querySelector('.world-heading').append(shortcuts);
const list=document.querySelector('#destinationList');
const search=document.createElement('input');search.type='search';search.className='destination-search';search.placeholder='Find a city or country';search.setAttribute('aria-label','Search destinations');list.before(search);search.oninput=()=>{const term=search.value.trim().toLowerCase();[...list.children].forEach((b,i)=>b.hidden=![destinations[i]?.city,destinations[i]?.country].join(' ').toLowerCase().includes(term));};
const enter=document.createElement('button');enter.className='direct-city';enter.textContent='Open city chapter · skip flight';enter.onclick=()=>window.zrOpenCity?.(document.querySelector('#worldCity').textContent);list.before(enter);
document.querySelectorAll('[data-station]').forEach(b=>{const ids=['identity','research','conferences','memories','contact'];b.onclick=()=>document.getElementById(ids[Number(b.dataset.station)])?.scrollIntoView({behavior:window.zrMotionPaused?'instant':'smooth'});});
